    console.log('\n=== hit in', s, '===')
    // Print context around each mention
    const rx = /(.{200})productsearch\/search(.{200})/g
    let m, count = 0
    while ((m = rx.exec(body)) && count < 6) {
      console.log('---')
      console.log((m[1] + '<<<productsearch/search>>>' + m[2]).replace(/\s+/g, ' '))
